# r107_caustics.fixed: reviewed copy of r107_caustics.py (review 2026-11-15; the faults fixed are
# listed at the end of this header). FEATURE patch (order item 1, glass/water/caustics for the sun and all lights;
# context file bbfss-ctx-glass-water-caustics.md, stage S4 "sun caustics as their own setting").
# Branch when published: visual/glass-water (feature only; nothing of the test tools inside).
#
# Water caustics from the sun or moon: the moving net of light that water reflects onto the walls
# and undersides beside it, where the game's sun shadow says the water is lit. Off by default
# behind BB_CAUSTICS (unset/0 off, 1 on, a number = strength up to 4, "show" = test view).
# BB_CAUSTICS_LAMPS is read only to say once that the lamps' caustics are not built in this stage.
#
# What the tree can tell apart today (and so what is drawn): the game's planar reflection draws
# the world a second time from the camera mirrored in the water plane (sewers, Gascoigne's arena;
# CameraMotion::MirroredPasses); the plane's height is the midpoint of the two cameras' heights
# (new accessor CameraMotion::MirrorPlane). The water (ps e3021062) is opaque and writes depth, and
# is drawn before the first blended draw (probe r64b: sewer water draw 706, first blended 710), so
# at that draw the depth on the plane IS the water. A pixel 0.03-4 m above the plane that faces the
# sun's light reflected off the plane gets the pattern of its water point Q (P traced back along
# the reflected light), when Q is on the screen, is water (depth on the plane, nothing in front)
# and is lit per the game's screen shadow target's alpha at Q. NOT drawn: anything under the water
# (opaque: never seen), puddles (painted gloss in the G-buffer, no draw or value told apart from
# wet stone by any probe so far; the test view paints the gloss candidates so a still can decide),
# lamps (needs the lamp pass, which runs before the water is drawn: a next stage).
#
# Files: new host_shaders/caustics.comp and caustics_layout.h, renderer_vulkan/caustics_params.h
# (pure: knob, push words, drift, the pattern's C++ twin), vk_caustics.h/.cpp (the pass),
# tests/test_caustics.cpp. Hooks: vk_rasterizer.h (include, member), vk_rasterizer.cpp (made only
# when Caustics::Wanted()), vk_rasterizer_effects.cpp (G-buffer draw, shadow resolve, blended scene),
# vk_camera_motion.h (MirrorPlane), engine/gpu/CMakeLists.txt (shader build, its include dependency,
# caustics-test), engine/build.sh (caustics-test), tests/test_effect_pipelines.cpp (the pipeline
# row), README.md (a section before "## Sponsors").
#
# Off: the rasterizer makes no Caustics (unique_ptr null); each hook is one null pointer test; no
# pipeline, buffer, image, pass or barrier; no existing shader build changes (a new header only).
#
# Use: python -I -X utf8 r107_caustics.fixed.py check | apply | revert. Root from R107_CAUSTICS_ROOT (or
# R107_ROOT), else <tree>. Files keep their line ends (CRLF in the tree); new files are
# written with CRLF. apply keeps the edited files' originals in r107_backup/ next to this script.
# Every inserted block is found by itself (exactly once), so revert takes out exactly this patch's
# blocks even when a later patch inserted text next to them; new files are removed only when
# unchanged. Exit codes: 0 done (or nothing to do), 1 refused (mixed state; nothing written), 2 usage.
#
# Review fixes (2026-11-15): (1) the shadow resolve's news is kept for the pass a water plane is
# found in (a mirror-image pass reaching its own blended draw first no longer uses it up); (2) a pass
# whose camera is below the plane (the mirror image) is never drawn into, counted as "mirror image";
# (3) a G-buffer draw of a pass already applied in the same frame does not arm the pass again (no
# double pattern); (4) the pattern is the mean of each layer's ridge to the 8th power (a net of thin
# lines; the draft's sharpened mean of both gave soft blotches), mean 0.1933 by Monte Carlo; (5) the
# wind shares 0.15 and 0.1 (0.5 and 0.3 moved the net about 4 pixels a frame on a near wall at the
# wind's default, with no motion vectors under the upscaler); (6) the once-line puts the knob, gain
# and test view inside the slot evidence's 300 characters; (7) the README states the drift speeds,
# the mirror rule, which effects the sun's direction needs, and view depth where it said distance.
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
BACKUP = os.path.join(HERE, "r107_backup")
ROOT = os.environ.get("R107_CAUSTICS_ROOT") or os.environ.get("R107_ROOT") or "<tree>"
V = "engine/gpu/shadps4/video_core/"
R = V + "renderer_vulkan/"
H = V + "host_shaders/"

NEW = {
    'engine/gpu/shadps4/video_core/host_shaders/caustics_layout.h': "// SPDX-License-Identifier: GPL-3.0-or-later\n// bbport (r107_caustics): the water caustics' numbers, shared by host_shaders/caustics.comp and\n// renderer_vulkan/caustics_params.h (which ties them to its C++ names with static_asserts and\n// the test). Plain #define lines only: GLSL and C++ both read this file.\n#ifndef CAUSTICS_LAYOUT_H\n#define CAUSTICS_LAYOUT_H\n\n// One workgroup: 8x8 pixels.\n#define CAUSTICS_GROUP 8\n\n// Push word `flags`.\n#define CAUSTICS_FLAG_SHOW 1u     // the test view (BB_CAUSTICS=show)\n#define CAUSTICS_FLAG_PLANE 2u    // a water plane, a sun or moon above the horizon and the\n                                  // screen shadow target: the caustics are drawn\n#define CAUSTICS_FLAG_MATERIAL 4u // the G-buffer's material target (gloss in .r) is bound\n\n// The counters: CAUSTICS_SLOTS slots of CAUSTICS_SLOT_WORDS words, one slot a dispatch, in turn.\n// Words: 0 pixels in the band above the water that face the reflected light, 1 of them whose\n// water point is water on the screen, 2 of them whose water point the sun shadow says is lit\n// (drawn), 3 puddle candidates painted by the test view.\n#define CAUSTICS_SLOT_WORDS 4\n#define CAUSTICS_SLOTS 8\n\n// Receivers: from CAUSTICS_MIN_HEIGHT to CAUSTICS_MAX_HEIGHT metres above the water plane, at\n// most CAUSTICS_MAX_PATH metres from their water point along the reflected light, facing it by\n// more than CAUSTICS_MIN_FACING (the cosine). Weight exp(-path / CAUSTICS_PATH_FALLOFF), faded out\n// between CAUSTICS_FADE_START and CAUSTICS_FADE_END metres of view depth.\n#define CAUSTICS_MIN_HEIGHT 0.03\n#define CAUSTICS_MAX_HEIGHT 4.0\n#define CAUSTICS_MAX_PATH 8.0\n#define CAUSTICS_PATH_FALLOFF 2.5\n#define CAUSTICS_MIN_FACING 0.05\n#define CAUSTICS_FADE_START 30.0\n#define CAUSTICS_FADE_END 45.0\n// The water point counts as water when the depth there lies on the plane within\n// CAUSTICS_WATER_M + CAUSTICS_WATER_REL x its view depth (m), and as seen (nothing in front of it)\n// when that depth is the point's own within CAUSTICS_SEEN_M + CAUSTICS_SEEN_REL x its depth.\n#define CAUSTICS_WATER_M 0.04\n#define CAUSTICS_WATER_REL 0.002\n#define CAUSTICS_SEEN_M 0.05\n#define CAUSTICS_SEEN_REL 0.03\n\n// The pattern: two layers of ridged value noise on the water (world x, z), cells of\n// CAUSTICS_LAMBDA1 and CAUSTICS_LAMBDA2 metres, the second turned by 37 degrees (CAUSTICS_COS2,\n// CAUSTICS_SIN2); each layer's ridge to the power CAUSTICS_SHARP (thin bright lines), the two\n// averaged (a net whose crossings are brightest), divided by CAUSTICS_PATTERN_MEAN (that average's\n// mean, from a Monte Carlo of this noise over 600000 points: 0.1933), so the pattern's mean is 1:\n// light is moved, not added. The third noise axis is the time: CAUSTICS_EVOLVE cells a second\n// (layer 2: x CAUSTICS_EVOLVE2, shifted by CAUSTICS_EVOLVE2_SHIFT cells).\n#define CAUSTICS_LAMBDA1 0.9\n#define CAUSTICS_LAMBDA2 0.55\n#define CAUSTICS_COS2 0.79863551\n#define CAUSTICS_SIN2 0.60181502\n#define CAUSTICS_SHARP 8.0\n#define CAUSTICS_PATTERN_MEAN 0.1933\n#define CAUSTICS_EVOLVE 0.3\n#define CAUSTICS_EVOLVE2 1.3\n#define CAUSTICS_EVOLVE2_SHIFT 17.0\n\n#endif\n",
    'engine/gpu/shadps4/video_core/host_shaders/caustics.comp': '// SPDX-License-Identifier: GPL-3.0-or-later\n// bbport (r107_caustics): water caustics from the sun or moon (BB_CAUSTICS; vk_caustics.cpp, the\n// numbers in caustics_layout.h). One dispatch over the scene at its render size, at the first\n// blended draw after the opaque scene (after the game\'s water, which is opaque and writes depth,\n// and after the indirect light; before the transparents and the fog).\n//\n// Where: only in frames whose G-buffer passes are the world and its mirror image in a water plane\n// (the game\'s planar reflection: the sewers, Gascoigne\'s arena); the plane\'s height comes from the\n// two cameras (CameraMotion::MirrorPlane). A pixel P from CAUSTICS_MIN_HEIGHT to MAX_HEIGHT above\n// the plane takes light the water reflects: the sun\'s light reflected off a flat plane travels\n// along r = (-s.x, s.y, -s.z) (s toward the sun), so P\'s water point is Q = P - r * height / r.y.\n// P is drawn when it faces r (normal from the depth), Q lies on the screen, the depth there is on\n// the plane at Q (water, nothing in front of it), and the game\'s screen shadow target (its alpha,\n// the sun\'s visibility the game\'s sun light reads; where water covers the screen it is the ground\n// under the water) says Q is lit.\n// What: P\'s colour times 1 + gain * w * (c - 1): c the caustic pattern at Q (two layers of ridged\n// value noise on the water, drifting, mean 1, so light is moved, not added), w = facing * lit at\n// Q * exp(-path / falloff), faded out with distance. Nothing under the water: the game\'s water is\n// opaque, the ground under it is never seen. Puddles are not lit: nothing tells a puddle from dry\n// ground yet; the test view paints the candidates (up-facing, by gloss) so a picture can say\n// whether gloss does.\n// Test view (CAUSTICS_FLAG_SHOW): drawn pixels tinted cyan, band pixels whose Q is not water\n// orange, those whose Q is in shadow blue, puddle candidates magenta.\n#version 450\n#extension GL_GOOGLE_include_directive : require\n#extension GL_EXT_samplerless_texture_functions : require\n\n#include "caustics_layout.h"\n\nlayout(local_size_x = CAUSTICS_GROUP, local_size_y = CAUSTICS_GROUP) in;\n\nlayout(binding = 0, rgba16f) uniform image2D scene_img;\nlayout(binding = 1) uniform texture2D depth_tex;    // D32, depth 0..1\nlayout(binding = 2) uniform texture2D shadow_tex;   // the game\'s screen shadow target (.a: lit)\nlayout(binding = 3) uniform texture2D material_tex; // G-buffer cb1 (.r: gloss)\nlayout(binding = 4, std430) buffer Counters {\n    uint counts[];\n};\n\n// caustics_params.h Push, field for field (128 bytes).\nlayout(push_constant) uniform Push {\n    vec4 proj;  // x scale, y scale, z scale, z offset\n    vec4 frame; // width, height, jitter x, jitter y (pixels)\n    vec4 inv0;  // view to world, 3x4 rows\n    vec4 inv1;\n    vec4 inv2;\n    vec4 sun;   // xyz: world direction toward the sun or moon (unit); w: the water plane\'s world y\n    vec4 drift; // layer 1 offset x, z; layer 2 offset x, z (m)\n    float gain;\n    float evolve; // the pattern\'s time axis, cells\n    uint flags;\n    uint slot;\n};\n\nshared uint group_counts[CAUSTICS_SLOT_WORDS];\n\nconst vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);\nconst vec3 TINT_DRAWN = vec3(0.15, 0.85, 1.0);\nconst vec3 TINT_DRY = vec3(1.0, 0.55, 0.1);\nconst vec3 TINT_SHADE = vec3(0.2, 0.3, 1.0);\nconst vec3 TINT_PUDDLE = vec3(1.0, 0.2, 0.9);\n\n// As heat_haze.comp\'s (and caustics_params.h\'s C++ twin).\nuint Hash(uvec3 v) {\n    v = v * 1664525u + 1013904223u;\n    v.x += v.y * v.z;\n    v.y += v.z * v.x;\n    v.z += v.x * v.y;\n    v ^= v >> 16u;\n    v.x += v.y * v.z;\n    return v.x;\n}\n\nfloat Corner(ivec3 c) {\n    return float(Hash(uvec3(c & 1023)) >> 8u) * (1.0 / 16777216.0);\n}\n\n// Value noise in [0, 1), smooth (quintic) between the lattice\'s corners.\nfloat Noise(vec3 p) {\n    const vec3 f = floor(p);\n    const ivec3 i = ivec3(f);\n    const vec3 u = p - f;\n    const vec3 s = u * u * u * (u * (u * 6.0 - 15.0) + 10.0);\n    const float x00 = mix(Corner(i), Corner(i + ivec3(1, 0, 0)), s.x);\n    const float x10 = mix(Corner(i + ivec3(0, 1, 0)), Corner(i + ivec3(1, 1, 0)), s.x);\n    const float x01 = mix(Corner(i + ivec3(0, 0, 1)), Corner(i + ivec3(1, 0, 1)), s.x);\n    const float x11 = mix(Corner(i + ivec3(0, 1, 1)), Corner(i + ivec3(1, 1, 1)), s.x);\n    return mix(mix(x00, x10, s.y), mix(x01, x11, s.y), s.z);\n}\n\n// 1 on the noise\'s 0.5 contour, 0 at its extremes: thin bright lines where it is sharpened.\nfloat Ridge(vec3 p) {\n    return 1.0 - abs(2.0 * Noise(p) - 1.0);\n}\n\n// The caustic pattern at a point of the water (world x, z), mean 1 (CAUSTICS_PATTERN_MEAN).\nfloat Pattern(vec2 xz) {\n    const vec2 a = (xz + drift.xy) * (1.0 / CAUSTICS_LAMBDA1);\n    const vec2 m = xz + drift.zw;\n    const vec2 b = vec2(CAUSTICS_COS2 * m.x - CAUSTICS_SIN2 * m.y,\n                        CAUSTICS_SIN2 * m.x + CAUSTICS_COS2 * m.y) *\n                   (1.0 / CAUSTICS_LAMBDA2);\n    const float r1 = Ridge(vec3(a, evolve));\n    const float r2 = Ridge(vec3(b, evolve * CAUSTICS_EVOLVE2 + CAUSTICS_EVOLVE2_SHIFT));\n    return 0.5 * (pow(r1, CAUSTICS_SHARP) + pow(r2, CAUSTICS_SHARP)) * (1.0 / CAUSTICS_PATTERN_MEAN);\n}\n\nfloat ViewZ(float depth) {\n    return proj.w / min(depth - proj.z, -1e-8);\n}\n\n// The view position seen at `pixel` (its centre: + 0.5) at view depth z; the jitter taken out.\nvec3 ViewPos(vec2 pixel, float z) {\n    const vec2 ndc = (pixel - frame.zw) / frame.xy * 2.0 - 1.0;\n    return vec3(ndc.x * z / proj.x, ndc.y * z / proj.y, z);\n}\n\nvec3 ViewAt(ivec2 p) {\n    return ViewPos(vec2(p) + 0.5, ViewZ(texelFetch(depth_tex, p, 0).r));\n}\n\nvec3 ToWorld(vec3 v) {\n    const vec4 h = vec4(v, 1.0);\n    return vec3(dot(inv0, h), dot(inv1, h), dot(inv2, h));\n}\n\nvec3 DirToWorld(vec3 v) {\n    return vec3(dot(inv0.xyz, v), dot(inv1.xyz, v), dot(inv2.xyz, v));\n}\n\n// World to view: the view to world rotation\'s transpose (a camera turns and moves, it does not\n// scale), after taking off the camera\'s position.\nvec3 ToView(vec3 w) {\n    const vec3 d = w - vec3(inv0.w, inv1.w, inv2.w);\n    return vec3(dot(vec3(inv0.x, inv1.x, inv2.x), d), dot(vec3(inv0.y, inv1.y, inv2.y), d),\n                dot(vec3(inv0.z, inv1.z, inv2.z), d));\n}\n\n// The surface\'s view normal from the depth, facing the camera: on each axis the neighbour whose\n// depth is nearer the pixel\'s (an edge does not bend it). Zero at the screen\'s border.\nvec3 NormalAt(ivec2 p, vec3 P) {\n    const ivec2 last = ivec2(frame.xy) - 1;\n    if (any(lessThanEqual(p, ivec2(0))) || any(greaterThanEqual(p, last))) {\n        return vec3(0.0);\n    }\n    const vec3 r = ViewAt(p + ivec2(1, 0)), l = ViewAt(p - ivec2(1, 0));\n    const vec3 d = ViewAt(p + ivec2(0, 1)), u = ViewAt(p - ivec2(0, 1));\n    const vec3 dx = abs(r.z - P.z) < abs(P.z - l.z) ? r - P : P - l;\n    const vec3 dy = abs(d.z - P.z) < abs(P.z - u.z) ? d - P : P - u;\n    const vec3 n = cross(dy, dx);\n    const float len = length(n);\n    if (!(len > 1e-12)) {\n        return vec3(0.0);\n    }\n    return dot(n, P) > 0.0 ? -n / len : n / len;\n}\n\nvec3 Tinted(vec3 rgb, vec3 tint, float k) {\n    const float luma = max(dot(max(rgb, vec3(0.0)), LUMA), 0.05);\n    return mix(rgb, tint * (luma / dot(tint, LUMA)), k);\n}\n\nvoid Shade(ivec2 p) {\n    const float depth = texelFetch(depth_tex, p, 0).r;\n    if (depth >= 1.0) {\n        return;\n    }\n    const vec3 P = ViewPos(vec2(p) + 0.5, ViewZ(depth));\n    const vec3 Pw = ToWorld(P);\n    const bool show = (flags & CAUSTICS_FLAG_SHOW) != 0u;\n    float factor = 1.0;\n    vec3 tint = vec3(0.0);\n    float tint_k = 0.0;\n    vec3 n = vec3(0.0);\n    bool have_n = false;\n    if (show && (flags & CAUSTICS_FLAG_MATERIAL) != 0u) {\n        // Puddle candidates: surfaces facing up, by their gloss (0.5 none, 0.95 full).\n        n = NormalAt(p, P);\n        have_n = true;\n        const float up = DirToWorld(n).y;\n        const float gloss = texelFetch(material_tex, p, 0).r;\n        const float k = smoothstep(0.5, 0.95, gloss) * smoothstep(0.85, 0.95, up);\n        if (k > 0.0) {\n            tint = TINT_PUDDLE;\n            tint_k = 0.5 * k;\n            atomicAdd(group_counts[3], 1u);\n        }\n    }\n    const float height = Pw.y - sun.w;\n    if ((flags & CAUSTICS_FLAG_PLANE) != 0u && height > CAUSTICS_MIN_HEIGHT &&\n        height < CAUSTICS_MAX_HEIGHT) {\n        // The sun\'s light reflected off the water travels along r (up: sun.y > 0, the host\'s test).\n        const vec3 r = vec3(-sun.x, sun.y, -sun.z);\n        if (!have_n) {\n            n = NormalAt(p, P);\n        }\n        const float facing = dot(DirToWorld(n), -r);\n        const float path = height / r.y;\n        if (facing > CAUSTICS_MIN_FACING && path < CAUSTICS_MAX_PATH) {\n            atomicAdd(group_counts[0], 1u);\n            const vec3 Qw = Pw - r * path;\n            const vec3 Qv = ToView(Qw);\n            const vec2 q = (Qv.xy * proj.xy / max(Qv.z, 1e-4) + 1.0) * 0.5 * frame.xy + frame.zw;\n            bool water = false;\n            ivec2 qi = ivec2(0);\n            if (Qv.z > 0.05 && all(greaterThanEqual(q, vec2(0.0))) && all(lessThan(q, frame.xy))) {\n                qi = ivec2(q);\n                const float dq = texelFetch(depth_tex, qi, 0).r;\n                if (dq < 1.0) {\n                    const float zq = ViewZ(dq);\n                    const vec3 D = ToWorld(ViewPos(vec2(qi) + 0.5, zq));\n                    water = abs(D.y - sun.w) < CAUSTICS_WATER_M + CAUSTICS_WATER_REL * zq &&\n                            abs(zq - Qv.z) < CAUSTICS_SEEN_M + CAUSTICS_SEEN_REL * Qv.z;\n                }\n            }\n            if (!water) {\n                if (show) {\n                    tint = TINT_DRY;\n                    tint_k = 0.25;\n                }\n            } else {\n                atomicAdd(group_counts[1], 1u);\n                // The shadow target at Q, at its own size when it is not the scene\'s.\n                const ivec2 shadow_size = textureSize(shadow_tex, 0);\n                ivec2 sq = qi;\n                if (any(greaterThanEqual(sq, shadow_size))) {\n                    sq = ivec2(q / frame.xy * vec2(shadow_size));\n                }\n                const float lit = clamp(texelFetch(shadow_tex, min(sq, shadow_size - 1), 0).a, 0.0, 1.0);\n                if (lit <= 0.01) {\n                    if (show) {\n                        tint = TINT_SHADE;\n                        tint_k = 0.25;\n                    }\n                } else {\n                    atomicAdd(group_counts[2], 1u);\n                    const float w = facing * lit * exp(-path / CAUSTICS_PATH_FALLOFF) *\n                                    (1.0 - smoothstep(CAUSTICS_FADE_START, CAUSTICS_FADE_END, P.z));\n                    factor = max(1.0 + gain * w * (Pattern(Qw.xz) - 1.0), 0.0);\n                    if (show) {\n                        tint = TINT_DRAWN;\n                        tint_k = 0.35 * w;\n                    }\n                }\n            }\n        }\n    }\n    if (factor == 1.0 && tint_k <= 0.0) {\n        return;\n    }\n    const vec4 s = imageLoad(scene_img, p);\n    vec3 rgb = s.rgb * factor;\n    if (tint_k > 0.0) {\n        rgb = Tinted(rgb, tint, tint_k);\n    }\n    imageStore(scene_img, p, vec4(rgb, s.a));\n}\n\nvoid main() {\n    if (gl_LocalInvocationIndex < CAUSTICS_SLOT_WORDS) {\n        group_counts[gl_LocalInvocationIndex] = 0u;\n    }\n    barrier();\n    const ivec2 p = ivec2(gl_GlobalInvocationID.xy);\n    if (all(lessThan(p, ivec2(frame.xy)))) {\n        Shade(p);\n    }\n    barrier();\n    if (gl_LocalInvocationIndex < CAUSTICS_SLOT_WORDS) {\n        const uint v = group_counts[gl_LocalInvocationIndex];\n        if (v != 0u) {\n            atomicAdd(counts[slot * CAUSTICS_SLOT_WORDS + gl_LocalInvocationIndex], v);\n        }\n    }\n}\n',
    'engine/gpu/shadps4/video_core/renderer_vulkan/caustics_params.h': '// SPDX-License-Identifier: GPL-3.0-or-later\n#pragma once\n\n// bbport (r107_caustics): water caustics from the sun or moon: the moving net of light that water\n// reflects onto the walls and undersides beside it, where the game\'s sun shadow says the water is\n// lit. The pass (vk_caustics.cpp, host_shaders/caustics.comp) runs at the first blended draw\n// after the opaque scene, in frames whose G-buffer passes are the world and its mirror image in a\n// water plane (the game\'s planar reflection: the sewers, Gascoigne\'s arena). This header holds\n// the knob, the push words, the pattern\'s drift and a C++ twin of the shader\'s pattern; no Vulkan\n// here: tests/test_caustics.cpp builds it alone.\n//\n// Knobs (environment, read once at the rasterizer\'s start; Parse):\n//   BB_CAUSTICS         unset, empty, 0, a negative number or text: off (nothing is made);\n//                       1: on; a number above 0: the strength (above MaxStrength counts as it);\n//                       "show": the test view at strength 1 (ShowGain times the pattern, tints)\n//   BB_CAUSTICS_LAMPS   not built in this stage (r107 is the sun and moon only): set to anything\n//                       but 0 it is said once and does nothing\n//\n// A receiver\'s colour is multiplied by 1 + Gain * strength * w * (c - 1), c the pattern (mean 1),\n// w its weight (caustics.comp): light moved, not added.\n\n#include <algorithm>\n#include <array>\n#include <cmath>\n#include <cstdint>\n#include <cstdlib>\n#include <cstring>\n\n#include "../host_shaders/caustics_layout.h"\n\nnamespace BbCaustics {\n\ninline constexpr float MaxStrength = 4.0f;\n/// The pattern\'s share at weight 1 and strength 1.\ninline constexpr float Gain = 0.3f;\n/// The test view: the pattern this many times as strong (tints as caustics.comp says).\ninline constexpr float ShowGain = 3.0f;\n/// The sun or moon must stand this high (the y of its unit direction) to light the water.\ninline constexpr float MinSunY = 0.02f;\n/// The pattern\'s drift without wind (m/s, world x and z), layer 1 and layer 2, and the share of\n/// the wind\'s velocity (BB_WIND) each layer takes on top: at the wind\'s default 1.5 m/s about\n/// 0.22 and 0.15 m/s, near the speed of small ripples and a pixel or two a frame on a wall a few\n/// metres away (the pattern has no motion vectors: faster drift trails under the upscaler).\ninline constexpr std::array<float, 2> Drift1{0.05f, 0.02f}, Drift2{-0.03f, 0.04f};\ninline constexpr float WindShare1 = 0.15f, WindShare2 = 0.1f;\n/// The longest step one Advance takes (s): a hitch does not jump the pattern.\ninline constexpr double MaxStep = 0.1;\n\n/// The shader\'s numbers (caustics_layout.h), named.\ninline constexpr std::uint32_t FlagShow = CAUSTICS_FLAG_SHOW, FlagPlane = CAUSTICS_FLAG_PLANE,\n                               FlagMaterial = CAUSTICS_FLAG_MATERIAL;\ninline constexpr std::uint32_t SlotWords = CAUSTICS_SLOT_WORDS, Slots = CAUSTICS_SLOTS;\ninline constexpr std::uint32_t Group = CAUSTICS_GROUP;\ninline constexpr float Lambda1 = CAUSTICS_LAMBDA1, Lambda2 = CAUSTICS_LAMBDA2;\ninline constexpr float Sharp = CAUSTICS_SHARP, PatternMean = CAUSTICS_PATTERN_MEAN;\ninline constexpr float Evolve = CAUSTICS_EVOLVE;\nstatic_assert(FlagShow == 1u && FlagPlane == 2u && FlagMaterial == 4u);\nstatic_assert(SlotWords == 4u && Slots >= 4u && Group == 8u);\nstatic_assert(CAUSTICS_MIN_HEIGHT < CAUSTICS_MAX_HEIGHT && CAUSTICS_FADE_START < CAUSTICS_FADE_END);\n\nstruct Knobs {\n    float strength = 0.0f; ///< 0: off\n    bool show = false;\n    bool unreadable = false;  ///< BB_CAUSTICS was set to text that is not a number nor "show"\n    bool lamps_asked = false; ///< BB_CAUSTICS_LAMPS set to something other than 0 (not built)\n};\n\ninline Knobs Parse(const char* caustics, const char* lamps) {\n    Knobs k;\n    k.lamps_asked = lamps != nullptr && lamps[0] != 0 && !(lamps[0] == \'0\' && lamps[1] == 0);\n    if (caustics == nullptr || caustics[0] == 0) {\n        return k;\n    }\n    if (std::strcmp(caustics, "show") == 0) {\n        k.show = true;\n        k.strength = 1.0f;\n        return k;\n    }\n    char* end = nullptr;\n    const float v = std::strtof(caustics, &end);\n    while (end != nullptr && (*end == \' \' || *end == \'\\t\')) {\n        ++end;\n    }\n    if (end == caustics || end == nullptr || *end != 0 || !std::isfinite(v)) {\n        k.unreadable = true;\n        return k;\n    }\n    k.strength = v > 0.0f ? std::min(v, MaxStrength) : 0.0f;\n    return k;\n}\n\n/// The push words of caustics.comp, field for field.\nstruct Push {\n    std::array<float, 4> proj{};      ///< x scale, y scale, z scale, z offset\n    std::array<float, 4> frame{};     ///< width, height, jitter x, jitter y (pixels)\n    std::array<float, 12> inv_view{}; ///< view to world, 3x4 rows\n    std::array<float, 4> sun{};       ///< toward the sun or moon (world, unit); the plane\'s world y\n    std::array<float, 4> drift{};     ///< layer 1 offset x, z; layer 2 offset x, z (m)\n    float gain = 0.0f;\n    float evolve = 0.0f; ///< the pattern\'s time axis, cells\n    std::uint32_t flags = 0;\n    std::uint32_t slot = 0;\n};\nstatic_assert(sizeof(Push) == 128);\n\n/// The gain the shader takes: Gain x strength, x ShowGain in the test view.\ninline float GainOf(const Knobs& k) {\n    return Gain * k.strength * (k.show ? ShowGain : 1.0f);\n}\n\n/// A direction toward the sun or moon the pass can use: finite, unit after scaling, above the\n/// horizon by MinSunY. `out` gets the unit direction.\ninline bool SunUsable(const std::array<float, 3>& toward, std::array<float, 3>& out) {\n    const float len = std::sqrt(toward[0] * toward[0] + toward[1] * toward[1] + toward[2] * toward[2]);\n    if (!std::isfinite(len) || !(len > 1e-6f)) {\n        return false;\n    }\n    out = {toward[0] / len, toward[1] / len, toward[2] / len};\n    return out[1] > MinSunY;\n}\n\n/// The pattern\'s drift and time, advanced by real seconds (clamped to MaxStep).\nstruct Drift {\n    std::array<double, 4> off{}; ///< layer 1 x, z; layer 2 x, z (m)\n    double time = 0.0;           ///< s\n    void Advance(double seconds, const std::array<float, 3>& wind) {\n        const double dt = std::isfinite(seconds) ? std::clamp(seconds, 0.0, MaxStep) : 0.0;\n        const auto finite = [](float v) { return std::isfinite(v) ? double(v) : 0.0; };\n        const double wx = finite(wind[0]), wz = finite(wind[2]);\n        off[0] += (Drift1[0] + WindShare1 * wx) * dt;\n        off[1] += (Drift1[1] + WindShare1 * wz) * dt;\n        off[2] += (Drift2[0] + WindShare2 * wx) * dt;\n        off[3] += (Drift2[1] + WindShare2 * wz) * dt;\n        // Layer 1 repeats every 1024 cells (the hash\'s period): kept small for the floats.\n        const double period = 1024.0 * double(Lambda1);\n        off[0] = std::fmod(off[0], period);\n        off[1] = std::fmod(off[1], period);\n        time += dt;\n    }\n    /// The time axis in cells, wrapped at the hash\'s period of 1024 (layer 2\'s axis jumps once\n    /// then: every 1024 / Evolve s, about 57 minutes).\n    [[nodiscard]] float EvolveCells() const {\n        return float(std::fmod(time * double(Evolve), 1024.0));\n    }\n    [[nodiscard]] std::array<float, 4> Offsets() const {\n        return {float(off[0]), float(off[1]), float(off[2]), float(off[3])};\n    }\n};\n\n// The shader\'s pattern on the CPU (caustics.comp Hash, Corner, Noise, Ridge, Pattern), for the\n// test: its mean is 1 and the GLSL copy has fixed values to match.\ninline std::uint32_t Hash(std::uint32_t x, std::uint32_t y, std::uint32_t z) {\n    x = x * 1664525u + 1013904223u;\n    y = y * 1664525u + 1013904223u;\n    z = z * 1664525u + 1013904223u;\n    x += y * z;\n    y += z * x;\n    z += x * y;\n    x ^= x >> 16u;\n    y ^= y >> 16u;\n    z ^= z >> 16u;\n    x += y * z;\n    return x;\n}\n\ninline float Corner(std::int32_t x, std::int32_t y, std::int32_t z) {\n    return float(Hash(std::uint32_t(x & 1023), std::uint32_t(y & 1023), std::uint32_t(z & 1023)) >> 8u) *\n           (1.0f / 16777216.0f);\n}\n\ninline float Noise(float px, float py, float pz) {\n    const float fx = std::floor(px), fy = std::floor(py), fz = std::floor(pz);\n    const auto ix = std::int32_t(fx), iy = std::int32_t(fy), iz = std::int32_t(fz);\n    const auto fade = [](float u) { return u * u * u * (u * (u * 6.0f - 15.0f) + 10.0f); };\n    const float sx = fade(px - fx), sy = fade(py - fy), sz = fade(pz - fz);\n    const auto lerp = [](float a, float b, float t) { return a + (b - a) * t; };\n    const float x00 = lerp(Corner(ix, iy, iz), Corner(ix + 1, iy, iz), sx);\n    const float x10 = lerp(Corner(ix, iy + 1, iz), Corner(ix + 1, iy + 1, iz), sx);\n    const float x01 = lerp(Corner(ix, iy, iz + 1), Corner(ix + 1, iy, iz + 1), sx);\n    const float x11 = lerp(Corner(ix, iy + 1, iz + 1), Corner(ix + 1, iy + 1, iz + 1), sx);\n    return lerp(lerp(x00, x10, sy), lerp(x01, x11, sy), sz);\n}\n\ninline float Ridge(float px, float py, float pz) {\n    return 1.0f - std::fabs(2.0f * Noise(px, py, pz) - 1.0f);\n}\n\ninline float Pattern(float x, float z, const std::array<float, 4>& drift, float evolve) {\n    const float ax = (x + drift[0]) / Lambda1, az = (z + drift[1]) / Lambda1;\n    const float mx = x + drift[2], mz = z + drift[3];\n    const float bx = (float(CAUSTICS_COS2) * mx - float(CAUSTICS_SIN2) * mz) / Lambda2;\n    const float bz = (float(CAUSTICS_SIN2) * mx + float(CAUSTICS_COS2) * mz) / Lambda2;\n    const float r1 = Ridge(ax, az, evolve);\n    const float r2 = Ridge(bx, bz, evolve * float(CAUSTICS_EVOLVE2) + float(CAUSTICS_EVOLVE2_SHIFT));\n    return 0.5f * (std::pow(r1, Sharp) + std::pow(r2, Sharp)) / PatternMean;\n}\n\n} // namespace BbCaustics\n',
    'engine/gpu/shadps4/video_core/renderer_vulkan/vk_caustics.h': '// SPDX-License-Identifier: GPL-3.0-or-later\n// bbport (r107_caustics): water caustics from the sun or moon, the moving net of light water\n// reflects onto the walls and undersides beside it (caustics_params.h says the knob and the\n// rule, host_shaders/caustics.comp the pass).\n//\n// Off unless BB_CAUSTICS names a strength above 0 or "show" (environment, read once). Off, the\n// rasterizer makes no Caustics (Wanted), so there is no pipeline, buffer or pass, and each of its\n// hooks is one null pointer test.\n//\n// Inputs, from the rasterizer\'s hooks: the G-buffer\'s material target (gloss, for the test view\'s\n// puddle candidates) at each G-buffer pass; the game\'s screen shadow target and the direction\n// toward the sun or moon at each shadow resolve (the volumetric light\'s SunLight); the water\n// plane from CameraMotion::MirrorPlane; the scene colour and depth at the first blended draw after\n// the opaque scene (Rasterizer::EffectsBlendedScene, which runs only with the upscaler on).\n#pragma once\n\n#include <array>\n#include <chrono>\n\n#include "common/types.h"\n#include "video_core/renderer_vulkan/caustics_params.h"\n#include "video_core/renderer_vulkan/vk_common.h"\n\n#include <vk_mem_alloc.h> // after vk_common.h: its Vulkan configuration first (as vk_halation.h)\n#include "video_core/texture_cache/image.h"\n\nnamespace VideoCore {\nclass TextureCache;\n}\n\nnamespace Vulkan {\nclass CameraMotion;\nclass Instance;\nclass PointShadow;\nclass Runtime;\nclass SceneTargets;\nclass Scheduler;\n\nclass Caustics {\npublic:\n    /// BB_CAUSTICS gives a strength above 0 or "show" (read once; the first call says the knobs).\n    [[nodiscard]] static bool Wanted();\n    Caustics(const Instance& instance, Scheduler& scheduler, VideoCore::TextureCache& texture_cache,\n             Runtime& runtime, SceneTargets& scene_targets, CameraMotion& camera_motion,\n             PointShadow& point_shadow, bool upscaler_on);\n    ~Caustics();\n    Caustics(const Caustics&) = delete;\n    Caustics& operator=(const Caustics&) = delete;\n\n    /// A G-buffer draw: its depth and its material target (cb 1, gloss in .r). It arms the pass:\n    /// Apply runs once after each G-buffer pass (at its first blended draw), not at every one; a\n    /// draw of a pass Apply already ran for (the same depth in the same frame) does not arm it\n    /// again, so a late G-buffer draw cannot apply the pattern twice.\n    void OnGBufferDraw(VideoCore::ImageId depth, VideoCore::ImageId material);\n    /// The game\'s shadow resolve: its target (the screen shadow target) and the direction toward\n    /// the sun or moon in the world (`valid`: known this frame).\n    void OnShadowResolve(VideoCore::ImageId target, const std::array<float, 3>& toward, bool valid);\n    /// The first blended draw after the opaque scene: the caustics into `color` (the scene colour,\n    /// RGBA16F), from `depth` (the scene\'s). `wind`: m/s in the world (zero without BB_WIND).\n    void Apply(VideoCore::ImageId color, VideoCore::ImageId depth, std::array<float, 2> jitter,\n               const std::array<float, 3>& wind);\n\nprivate:\n    struct ViewEntry {\n        vk::Image image{};\n        u64 uid = 0;\n        vk::ImageAspectFlags aspect{};\n        vk::ImageView view{};\n        u64 last_use = 0;\n    };\n    vk::ImageView CachedView(const VideoCore::Image& image, vk::ImageAspectFlags aspect);\n    void Report();\n\n    const Instance& instance;\n    Scheduler& scheduler;\n    VideoCore::TextureCache& texture_cache;\n    Runtime& runtime;\n    SceneTargets& scene_targets;\n    CameraMotion& camera_motion;\n    PointShadow& point_shadow;\n\n    ::BbCaustics::Knobs knobs;\n    ::BbCaustics::Drift drift;\n    vk::UniqueDescriptorSetLayout set_layout;\n    vk::UniquePipelineLayout layout;\n    vk::UniquePipeline pipeline;\n    struct Buffer {\n        vk::Buffer buffer{};\n        VmaAllocation allocation{};\n        void* mapped = nullptr;\n    } counters;\n    bool made = false;\n    std::array<ViewEntry, 6> view_cache{};\n    u64 view_uses = 0;\n    std::chrono::steady_clock::time_point last_time = std::chrono::steady_clock::now();\n\n    VideoCore::ImageId gbuffer_depth{}, gbuffer_material{};\n    VideoCore::ImageId shadow_target{};\n    std::array<float, 3> sun{};\n    bool sun_valid = false;\n    bool resolved = false; ///< a shadow resolve came since the last Apply that found a plane\n    bool armed = false;    ///< a G-buffer draw came since the last Apply\n    VideoCore::ImageId applied_depth{}; ///< the depth of the pass Apply last ran for\n    u32 applied_frame = 0;              ///< and its frame (BbStats::frame_number)\n    u32 dispatches = 0;    ///< the counter slot is dispatches % Slots\n    float last_plane = 0.0f, last_sun_y = 0.0f;\n\n    /// For the line after the first 120 calls, then every 600.\n    struct Stats {\n        u32 calls = 0;     ///< Apply calls (a mirrored frame calls twice: its mirror image too)\n        u32 drawn = 0;     ///< dispatches with the caustics (a water plane, the sun and its shadow)\n        u32 shown = 0;     ///< test view dispatches with puddle candidates only\n        u32 no_plane = 0;  ///< no water plane (no mirrored G-buffer passes): nothing to do\n        u32 mirror = 0;    ///< a plane, but this pass\'s camera is below it (the mirror image)\n        u32 no_sun = 0;    ///< a plane, but no sun direction this frame or the sun below MinSunY\n        u32 no_shadow = 0; ///< a plane and the sun, but no usable screen shadow target\n        u32 no_scene = 0;  ///< the scene colour was not a writable RGBA16F image, or no camera\n        u32 lamp_ends = 0; ///< lamps-apart batches this pass ended (it reads the camera depth)\n        std::array<u64, ::BbCaustics::SlotWords> pixels{}; ///< the shader\'s counts, read back late\n        u32 read = 0;      ///< dispatches whose counts were read\n    } stats;\n    bool reported = false;\n    bool told_first = false;\n};\n\n} // namespace Vulkan\n',
    'engine/gpu/shadps4/video_core/renderer_vulkan/vk_caustics.cpp': '// SPDX-License-Identifier: GPL-3.0-or-later\n// bbport (r107_caustics): water caustics from the sun or moon (vk_caustics.h; the knob and the\n// numbers in caustics_params.h, the pass in host_shaders/caustics.comp).\n\n#include "video_core/renderer_vulkan/vk_caustics.h"\n\n#include <algorithm>\n#include <cmath>\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n\n#include "bbport_toggles.h"\n#include "video_core/host_shaders/caustics_comp.h"\n#include "video_core/renderer_vulkan/vk_camera_motion.h"\n#include "video_core/renderer_vulkan/vk_effect_pass.h"\n#include "video_core/renderer_vulkan/vk_instance.h"\n#include "video_core/renderer_vulkan/vk_platform.h"\n#include "video_core/renderer_vulkan/vk_point_shadow.h"\n#include "video_core/renderer_vulkan/vk_runtime.h"\n#include "video_core/renderer_vulkan/vk_scene_resolution.h"\n#include "video_core/renderer_vulkan/vk_scheduler.h"\n#include "video_core/texture_cache/texture_cache.h"\n\nnamespace Vulkan {\nnamespace {\nnamespace BC = ::BbCaustics;\nconstexpr auto Compute = vk::PipelineStageFlagBits2::eComputeShader;\nconstexpr auto AllCommands = vk::PipelineStageFlagBits2::eAllCommands;\nconstexpr auto Host = vk::PipelineStageFlagBits2::eHost;\nconstexpr auto ShaderRead = vk::AccessFlagBits2::eShaderRead;\nconstexpr auto ReadWrite = vk::AccessFlagBits2::eShaderRead | vk::AccessFlagBits2::eShaderWrite;\nconstexpr auto MemoryAll = vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite;\nconstexpr auto StorageImage = vk::DescriptorType::eStorageImage;\nconstexpr auto SampledImage = vk::DescriptorType::eSampledImage;\nconstexpr auto StorageBuffer = vk::DescriptorType::eStorageBuffer;\nconstexpr u32 LineCalls = 600;\nconstexpr u32 FirstLineCalls = 120; ///< the first line comes sooner, for short test runs\nconstexpr u64 ProfileRow = 107;     ///< EffectPass::Mark: the row "Lighting: water caustics"\nconstexpr vk::DeviceSize SlotBytes = BC::SlotWords * sizeof(u32);\nconstexpr vk::DeviceSize CounterBytes = BC::Slots * SlotBytes;\n\n/// BB_CAUSTICS and BB_CAUSTICS_LAMPS, read once (the first caller: Wanted, at the rasterizer\'s\n/// start). Set to something that is off, it says so.\nconst BC::Knobs& ReadKnobs() {\n    static const BC::Knobs knobs = [] {\n        const char* value = std::getenv("BB_CAUSTICS");\n        const BC::Knobs read = BC::Parse(value, std::getenv("BB_CAUSTICS_LAMPS"));\n        if (read.unreadable) {\n            std::printf("Water caustics (r107): BB_CAUSTICS=%.16s is neither a number nor show: off\\n",\n                        value);\n        } else if (value != nullptr && value[0] != 0 && !(read.strength > 0.0f)) {\n            std::printf("Water caustics (r107): BB_CAUSTICS=%.16s: off\\n", value);\n        }\n        if (read.lamps_asked) {\n            std::printf("Water caustics (r107): BB_CAUSTICS_LAMPS is not built in this stage (the sun "\n                        "and moon only): it does nothing\\n");\n        }\n        return read;\n    }();\n    return knobs;\n}\n\nvk::DescriptorImageInfo Info(vk::ImageView view) {\n    return {.imageView = view, .imageLayout = vk::ImageLayout::eGeneral};\n}\n\nvk::WriteDescriptorSet Write(u32 binding, vk::DescriptorType type,\n                             const vk::DescriptorImageInfo* image) {\n    return {.dstBinding = binding, .descriptorCount = 1, .descriptorType = type,\n            .pImageInfo = image};\n}\n\n/// Four 8-bit channels (the game\'s screen shadow target, the G-buffer\'s material target).\nbool FourBytes(const VideoCore::Image& image) {\n    const auto f = image.info.pixel_format;\n    return f == vk::Format::eR8G8B8A8Unorm || f == vk::Format::eB8G8R8A8Unorm ||\n           f == vk::Format::eA8B8G8R8UnormPack32;\n}\n} // namespace\n\nbool Caustics::Wanted() {\n    return ReadKnobs().strength > 0.0f;\n}\n\nCaustics::Caustics(const Instance& instance_, Scheduler& scheduler_,\n                   VideoCore::TextureCache& texture_cache_, Runtime& runtime_,\n                   SceneTargets& scene_targets_, CameraMotion& camera_motion_,\n                   PointShadow& point_shadow_, bool upscaler_on)\n    : instance{instance_}, scheduler{scheduler_}, texture_cache{texture_cache_}, runtime{runtime_},\n      scene_targets{scene_targets_}, camera_motion{camera_motion_}, point_shadow{point_shadow_},\n      knobs{ReadKnobs()} {\n    // The pipeline and the counters are made here, at the start (no compile in play).\n    made = EffectPass::StorageFormat(instance, vk::Format::eR16G16B16A16Sfloat) &&\n           EffectPass::Create(instance, set_layout, layout, pipeline,\n                              {StorageImage, SampledImage, SampledImage, SampledImage, StorageBuffer},\n                              sizeof(BC::Push), CAUSTICS_COMP, "Water caustics");\n    if (made) {\n        const VkBufferCreateInfo buffer_ci{\n            .sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,\n            .size = CounterBytes,\n            .usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT,\n        };\n        VmaAllocationCreateInfo alloc_ci{};\n        alloc_ci.usage = VMA_MEMORY_USAGE_AUTO;\n        alloc_ci.requiredFlags = VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;\n        alloc_ci.flags = VMA_ALLOCATION_CREATE_MAPPED_BIT | VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT;\n        VkBuffer raw{};\n        VmaAllocationInfo info{};\n        if (vmaCreateBuffer(instance.GetAllocator(), &buffer_ci, &alloc_ci, &raw,\n                            &counters.allocation, &info) == VK_SUCCESS) {\n            counters.buffer = raw;\n            counters.mapped = info.pMappedData;\n        }\n        made = counters.mapped != nullptr;\n        if (made) {\n            std::memset(counters.mapped, 0, CounterBytes);\n        }\n    }\n    std::printf("Water caustics (r107, BB_CAUSTICS=%s%.2f): %s; gain %.2f, test view %s; sun or moon "\n                "light a water plane reflects (frames with the game\'s mirrored passes), as a moving "\n                "pattern on what stands 0.03 to 4 m above it facing that light; no puddles, no lamps\\n",\n                knobs.show ? "show, " : "", double(knobs.strength),\n                made ? "on" : "off - the pass could not be made", double(BC::GainOf(knobs)),\n                knobs.show ? "on" : "off");\n    if (!upscaler_on) {\n        std::printf("Water caustics (r107): not drawn - the upscaler is not available (BB_UPSCALER=none, "\n                    "or this GPU cannot run it), and the pass runs at its first blended draw\\n");\n    }\n}\n\nCaustics::~Caustics() {\n    const auto device = instance.GetDevice();\n    for (const auto& entry : view_cache) {\n        if (entry.view) {\n            device.destroyImageView(entry.view);\n        }\n    }\n    if (counters.buffer) {\n        vmaDestroyBuffer(instance.GetAllocator(), counters.buffer, counters.allocation);\n    }\n}\n\nvoid Caustics::OnGBufferDraw(VideoCore::ImageId depth, VideoCore::ImageId material) {\n    gbuffer_depth = depth;\n    gbuffer_material = material;\n    armed = armed || depth != applied_depth ||\n            BbStats::frame_number.load(std::memory_order_relaxed) != applied_frame;\n}\n\nvoid Caustics::OnShadowResolve(VideoCore::ImageId target, const std::array<float, 3>& toward,\n                               bool valid) {\n    std::array<float, 3> unit{};\n    const bool above = valid && BC::SunUsable(toward, unit);\n    if (valid) {\n        last_sun_y = unit[1];\n    }\n    shadow_target = target;\n    sun = unit;\n    sun_valid = above;\n    resolved = true;\n}\n\nvk::ImageView Caustics::CachedView(const VideoCore::Image& image, vk::ImageAspectFlags aspect) {\n    const vk::Image handle = image.GetImage();\n    ViewEntry* oldest = &view_cache[0];\n    for (auto& entry : view_cache) {\n        if (entry.view && entry.image == handle && entry.uid == image.image_uid &&\n            entry.aspect == aspect) {\n            entry.last_use = ++view_uses;\n            return entry.view;\n        }\n        if (entry.last_use < oldest->last_use) {\n            oldest = &entry;\n        }\n    }\n    const auto device = instance.GetDevice();\n    if (oldest->view) {\n        scheduler.DeferOperation([device, view = oldest->view] { device.destroyImageView(view); });\n    }\n    *oldest = {\n        .image = handle,\n        .uid = image.image_uid,\n        .aspect = aspect,\n        .view = Check<"create water caustics view">(device.createImageView({\n            .image = handle,\n            .viewType = vk::ImageViewType::e2D,\n            .format = image.info.pixel_format,\n            .subresourceRange = {aspect, 0, 1, 0, 1},\n        })),\n        .last_use = ++view_uses,\n    };\n    return oldest->view;\n}\n\nvoid Caustics::Apply(VideoCore::ImageId color_id, VideoCore::ImageId depth_id,\n                     std::array<float, 2> jitter, const std::array<float, 3>& wind) {\n    // Once after each G-buffer pass: the rasterizer calls at every blended draw of the scene.\n    if (!armed) {\n        return;\n    }\n    armed = false;\n    applied_depth = gbuffer_depth;\n    applied_frame = BbStats::frame_number.load(std::memory_order_relaxed);\n    ++stats.calls;\n    // Real time (clamped steps), so the pattern drifts at its speed at any frame rate.\n    const auto now = std::chrono::steady_clock::now();\n    drift.Advance(std::chrono::duration<double>(now - last_time).count(), wind);\n    last_time = now;\n    const auto done = [&] {\n        if (stats.calls >= (reported ? LineCalls : FirstLineCalls)) {\n            reported = true;\n            Report();\n        }\n    };\n    if (!made || !color_id || !depth_id) {\n        done();\n        return;\n    }\n    float plane_y = 0.0f;\n    const bool plane = camera_motion.MirrorPlane(plane_y) && std::isfinite(plane_y);\n    const auto camera = camera_motion.PassMatrices();\n    bool draw = plane;\n    if (!plane) {\n        // The first pass of a mirrored frame (the mirror image) comes here too: it leaves the\n        // shadow resolve\'s news for the pass the plane is found in.\n        ++stats.no_plane;\n    } else {\n        // The sun and its shadow target are this frame\'s only when a resolve came since the last\n        // call that found a plane.\n        const bool fresh = resolved;\n        resolved = false;\n        if (camera.valid && camera.inv_view[7] < plane_y) {\n            // The camera is below the water: this pass is the mirror image, not the world.\n            ++stats.mirror;\n            draw = false;\n        } else if (!fresh || !sun_valid) {\n            ++stats.no_sun;\n            draw = false;\n        }\n    }\n    if (!draw && !knobs.show) {\n        done();\n        return;\n    }\n    auto& color = texture_cache.GetImage(color_id);\n    auto& depth = texture_cache.GetImage(depth_id);\n    if (!camera.valid || color.info.pixel_format != vk::Format::eR16G16B16A16Sfloat) {\n        ++stats.no_scene;\n        done();\n        return;\n    }\n    VideoCore::Image* shadow = nullptr;\n    if (draw && shadow_target) {\n        shadow = &texture_cache.GetImage(shadow_target);\n        if (!FourBytes(*shadow)) {\n            shadow = nullptr;\n        }\n    }\n    VideoCore::Image* material = nullptr;\n    if (knobs.show && gbuffer_material && gbuffer_depth == depth_id) {\n        material = &texture_cache.GetImage(gbuffer_material);\n        if (!FourBytes(*material)) {\n            material = nullptr;\n        }\n    }\n    // The scene\'s size is the reduced one while a preset renders below the game\'s own size,\n    // else the game\'s render size (its targets may be allocated larger).\n    const bool reduced = scene_targets.Reduced() && scene_targets.EligibleScene(color);\n    u32 width = color.info.size.width, height = color.info.size.height;\n    if (reduced) {\n        width = scene_targets.Size().width;\n        height = scene_targets.Size().height;\n        // Only scene-sized images have a reduced proxy: the others are left out.\n        if (shadow && !scene_targets.EligibleScene(*shadow)) {\n            shadow = nullptr;\n        }\n        if (material && !scene_targets.EligibleScene(*material)) {\n            material = nullptr;\n        }\n    } else if (const auto render = camera_motion.RenderSize(); render[0] && render[1]) {\n        width = std::min(width, render[0]);\n        height = std::min(height, render[1]);\n    }\n    if (draw && !shadow) {\n        ++stats.no_shadow;\n        draw = false;\n    }\n    if ((!draw && !material) || width < 16 || height < 16) {\n        done();\n        return;\n    }\n    // The pass reads the camera depth: a lamps-apart batch still open ends first (only here,\n    // right before a dispatch, so it is never split for nothing).\n    if (point_shadow.Apart()) {\n        point_shadow.EndApart(jitter[0] != 0.0f || jitter[1] != 0.0f);\n        ++stats.lamp_ends;\n    }\n    const SceneUseScope scene_use{"water caustics"};\n    scheduler.EndRendering();\n    vk::ImageView color_view{}, depth_view{}, shadow_view{}, material_view{};\n    if (reduced) {\n        VideoCore::ImageViewInfo color_info, depth_info;\n        color_info.format = color.info.pixel_format;\n        depth_info.format = depth.info.pixel_format;\n        const auto proxy = scene_targets.Read(color_id, color_info, Compute, ReadWrite);\n        if (!(proxy.usage & vk::ImageUsageFlagBits::eStorage)) {\n            ++stats.no_scene;\n            done();\n            return;\n        }\n        color_view = proxy.view;\n        depth_view = scene_targets.ReadNext(depth_id, depth_info).view;\n        if (shadow) {\n            VideoCore::ImageViewInfo info;\n            info.format = shadow->info.pixel_format;\n            shadow_view = scene_targets.ReadNext(shadow_target, info).view;\n        }\n        if (material) {\n            VideoCore::ImageViewInfo info;\n            info.format = material->info.pixel_format;\n            material_view = scene_targets.ReadNext(gbuffer_material, info).view;\n        }\n    } else {\n        if (!(color.usage_flags & vk::ImageUsageFlagBits::eStorage)) {\n            ++stats.no_scene;\n            done();\n            return;\n        }\n        color_view = CachedView(color, vk::ImageAspectFlagBits::eColor);\n        depth_view = CachedView(depth, vk::ImageAspectFlagBits::eDepth);\n        runtime.Transit(&color, vk::ImageLayout::eGeneral, Compute, ReadWrite);\n        runtime.Transit(&depth, vk::ImageLayout::eGeneral, Compute, ShaderRead);\n        if (shadow) {\n            shadow_view = CachedView(*shadow, vk::ImageAspectFlagBits::eColor);\n            runtime.Transit(shadow, vk::ImageLayout::eGeneral, Compute, ShaderRead);\n        }\n        if (material) {\n            material_view = CachedView(*material, vk::ImageAspectFlagBits::eColor);\n            runtime.Transit(material, vk::ImageLayout::eGeneral, Compute, ShaderRead);\n        }\n        runtime.FlushBarriers();\n    }\n    scheduler.EndRendering();\n    if (draw && !shadow_view) {\n        ++stats.no_shadow;\n        draw = false;\n    }\n    if (!draw && !material_view) {\n        done();\n        return;\n    }\n    BC::Push push{};\n    push.proj = camera.proj;\n    push.frame = {float(width), float(height), jitter[0], jitter[1]};\n    push.inv_view = camera.inv_view;\n    push.sun = {sun[0], sun[1], sun[2], plane_y};\n    push.drift = drift.Offsets();\n    push.gain = BC::GainOf(knobs);\n    push.evolve = drift.EvolveCells();\n    push.flags = (knobs.show ? BC::FlagShow : 0u) | (draw ? BC::FlagPlane : 0u) |\n                 (material_view ? BC::FlagMaterial : 0u);\n    push.slot = dispatches % BC::Slots;\n    // The shader\'s counts of the dispatch Slots - 1 before this one (its work is long done; the\n    // slot is cleared on the GPU before its next use, which is the next dispatch).\n    if (dispatches + 1 >= BC::Slots) {\n        const auto* words = static_cast<const u32*>(counters.mapped) +\n                            ((dispatches + 1) % BC::Slots) * BC::SlotWords;\n        for (u32 i = 0; i < BC::SlotWords; ++i) {\n            stats.pixels[i] += words[i];\n        }\n        ++stats.read;\n    }\n    ++dispatches;\n    stats.drawn += draw ? 1 : 0;\n    stats.shown += draw ? 0 : 1;\n    last_plane = plane ? plane_y : last_plane;\n    if (!told_first && draw) {\n        told_first = true;\n        std::printf("Water caustics (r107): first caustics drawn: water plane at y %.2f, sun or moon "\n                    "%.2f up, scene %ux%u (%s)\\n",\n                    double(plane_y), double(sun[1]), width, height,\n                    reduced ? "reduced scene" : "the game\'s scene");\n    }\n    // Unbound inputs take the depth\'s view (the shader reads them only under their flag).\n    const vk::ImageView bound_shadow = shadow_view ? shadow_view : depth_view;\n    const vk::ImageView bound_material = material_view ? material_view : depth_view;\n    EffectPass::Mark(ProfileRow, "water caustics");\n    scheduler.RecordCrumb(\n        {.name = "water caustics"},\n        [push, width, height, color_view, depth_view, bound_shadow, bound_material,\n         counter_buffer = counters.buffer, pass_pipeline = *pipeline,\n         pass_layout = *layout](vk::CommandBuffer cmdbuf) {\n            cmdbuf.fillBuffer(counter_buffer, push.slot * SlotBytes, SlotBytes, 0);\n            EffectPass::MemoryBarrier(cmdbuf, AllCommands, vk::AccessFlagBits2::eMemoryWrite,\n                                      Compute, ReadWrite);\n            cmdbuf.bindPipeline(vk::PipelineBindPoint::eCompute, pass_pipeline);\n            const std::array infos{Info(color_view), Info(depth_view), Info(bound_shadow),\n                                   Info(bound_material)};\n            const vk::DescriptorBufferInfo counter_info{counter_buffer, 0, CounterBytes};\n            const std::array writes{Write(0, StorageImage, &infos[0]),\n                                    Write(1, SampledImage, &infos[1]),\n                                    Write(2, SampledImage, &infos[2]),\n                                    Write(3, SampledImage, &infos[3]),\n                                    vk::WriteDescriptorSet{.dstBinding = 4,\n                                                           .descriptorCount = 1,\n                                                           .descriptorType = StorageBuffer,\n                                                           .pBufferInfo = &counter_info}};\n            cmdbuf.pushDescriptorSetKHR(vk::PipelineBindPoint::eCompute, pass_layout, 0, writes);\n            cmdbuf.pushConstants(pass_layout, vk::ShaderStageFlagBits::eCompute, 0, sizeof(push),\n                                 &push);\n            cmdbuf.dispatch((width + BC::Group - 1) / BC::Group, (height + BC::Group - 1) / BC::Group,\n                            1);\n            EffectPass::MemoryBarrier(cmdbuf, Compute, vk::AccessFlagBits2::eShaderWrite,\n                                      AllCommands | Host, MemoryAll | vk::AccessFlagBits2::eHostRead);\n        });\n    done();\n}\n\nvoid Caustics::Report() {\n    const double reads = std::max(1.0, double(stats.read));\n    BbReport::Printf(\n        "Water caustics (r107): %u calls, %u drew, %u test view only; skipped: %u no water plane, %u "\n        "mirror image, %u no sun, %u no shadow target, %u no scene; plane y %.2f, sun %.2f up; a "\n        "dispatch: %.0f px facing, %.0f on water, %.0f drawn, %.0f puddle cand.; %u lamp batch ends\\n",\n        stats.calls, stats.drawn, stats.shown, stats.no_plane, stats.mirror, stats.no_sun,\n        stats.no_shadow, stats.no_scene, double(last_plane), double(last_sun_y),\n        double(stats.pixels[0]) / reads,\n        double(stats.pixels[1]) / reads, double(stats.pixels[2]) / reads,\n        double(stats.pixels[3]) / reads, stats.lamp_ends);\n    stats = {};\n}\n\n} // namespace Vulkan\n',
    'engine/tests/test_caustics.cpp': '// SPDX-License-Identifier: GPL-3.0-or-later\n// bbport (r107_caustics): the water caustics\' knob, push words, drift and pattern\n// (renderer_vulkan/caustics_params.h). Built by engine/build.sh --test (C++20, -Werror) and by the\n// CMake target caustics-test.\n#include <algorithm>\n#include <array>\n#include <cassert>\n#include <cmath>\n#include <cstddef>\n#include <cstdio>\n\n#include "gpu/shadps4/video_core/renderer_vulkan/caustics_params.h"\n\nusing namespace BbCaustics;\n\nstatic bool Near(float a, float b, float tol) {\n    return std::fabs(a - b) <= tol;\n}\n\nint main() {\n    // The knob: off unless a strength above 0 or "show".\n    assert(Parse(nullptr, nullptr).strength == 0.0f);\n    assert(Parse("", nullptr).strength == 0.0f && !Parse("", nullptr).unreadable);\n    assert(Parse("0", nullptr).strength == 0.0f);\n    assert(Parse("-1", nullptr).strength == 0.0f);\n    assert(Parse("1", nullptr).strength == 1.0f && !Parse("1", nullptr).show);\n    assert(Parse("2.5", nullptr).strength == 2.5f);\n    assert(Parse("9", nullptr).strength == MaxStrength);\n    assert(Parse("1 ", nullptr).strength == 1.0f);\n    assert(Parse("yes", nullptr).unreadable && Parse("yes", nullptr).strength == 0.0f);\n    assert(Parse("1x", nullptr).unreadable);\n    assert(Parse("nan", nullptr).strength == 0.0f);\n    const Knobs show = Parse("show", nullptr);\n    assert(show.show && show.strength == 1.0f && Near(GainOf(show), Gain * ShowGain, 1e-6f));\n    assert(Near(GainOf(Parse("2", nullptr)), 2.0f * Gain, 1e-6f));\n    assert(!Parse("1", nullptr).lamps_asked && !Parse("1", "0").lamps_asked && !Parse("1", "").lamps_asked);\n    assert(Parse("1", "1").lamps_asked && Parse(nullptr, "2").lamps_asked);\n\n    // The push block is the shader\'s (caustics.comp Push): 128 bytes, the fields in order.\n    static_assert(sizeof(Push) == 128);\n    static_assert(offsetof(Push, inv_view) == 32 && offsetof(Push, sun) == 80 && offsetof(Push, drift) == 96);\n    static_assert(offsetof(Push, gain) == 112 && offsetof(Push, evolve) == 116 && offsetof(Push, flags) == 120 &&\n                  offsetof(Push, slot) == 124);\n\n    // The sun: unit, above the horizon.\n    std::array<float, 3> s{};\n    assert(SunUsable({0.0f, 2.0f, 0.0f}, s) && Near(s[1], 1.0f, 1e-6f));\n    assert(!SunUsable({1.0f, 0.0f, 0.0f}, s));\n    assert(!SunUsable({0.3f, -0.5f, 0.1f}, s));\n    assert(!SunUsable({0.0f, 0.0f, 0.0f}, s));\n    assert(!SunUsable({NAN, 1.0f, 0.0f}, s));\n\n    // The drift: real seconds, clamped; the wind adds its shares; layer 1 wraps at its period.\n    Drift d;\n    d.Advance(1.0, {0.0f, 0.0f, 0.0f}); // clamped to MaxStep\n    assert(Near(float(d.time), float(MaxStep), 1e-9f));\n    assert(Near(float(d.off[0]), Drift1[0] * float(MaxStep), 1e-7f));\n    Drift w;\n    w.Advance(0.1, {2.0f, 0.0f, -1.0f});\n    assert(Near(float(w.off[0]), (Drift1[0] + WindShare1 * 2.0f) * 0.1f, 1e-6f));\n    assert(Near(float(w.off[3]), (Drift2[1] - WindShare2 * 1.0f) * 0.1f, 1e-6f));\n    w.Advance(-1.0, {NAN, 0.0f, 0.0f});\n    assert(Near(float(w.time), 0.1f, 1e-9f));\n    Drift far;\n    for (int i = 0; i < 400000; ++i) {\n        far.Advance(0.1, {40.0f, 0.0f, 0.0f});\n    }\n    assert(far.off[0] < 1024.0 * Lambda1 && far.off[0] > -1024.0 * Lambda1);\n    assert(far.EvolveCells() >= 0.0f && far.EvolveCells() < 1024.0f);\n\n    // The noise: the values the shader\'s copy must give (from the Monte Carlo script\'s twin).\n    assert(Near(Noise(0.25f, 0.5f, 0.75f), 0.6614143f, 2e-5f));\n    assert(Near(Noise(12.3f, -7.9f, 3.1f), 0.6591443f, 2e-5f));\n    assert(Near(Noise(-500.5f, 1023.9f, 40.0f), 0.3346269f, 2e-4f));\n    assert(Near(Ridge(0.25f, 0.5f, 0.75f), 0.6771714f, 4e-5f));\n\n    // The pattern\'s mean is 1 (PatternMean), its values from 0 to 1 / PatternMean.\n    double sum = 0.0;\n    float most = 0.0f, least = 1e9f;\n    const std::array<float, 4> drift{1.5f, -2.0f, 3.0f, 0.5f};\n    int n = 0;\n    for (int i = 0; i < 400; ++i) {\n        for (int j = 0; j < 400; ++j) {\n            const float c = Pattern(-150.0f + 0.7531f * float(i), 80.0f + 0.6917f * float(j), drift,\n                                    0.37f * float((i * 7 + j * 13) % 997));\n            sum += c;\n            most = std::max(most, c);\n            least = std::min(least, c);\n            ++n;\n        }\n    }\n    const double mean = sum / n;\n    assert(mean > 0.96 && mean < 1.04);\n    assert(least >= 0.0f && most <= 1.0f / PatternMean + 1e-3f);\n    std::printf("caustics: ok (pattern mean %.4f over %d points, %.3f to %.3f)\\n", mean, n, double(least),\n                double(most));\n    return 0;\n}\n',
}

